:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #23352c;
  background: #f5edda;
}

* { box-sizing: border-box; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #f5edda;
  background-image: radial-gradient(#d7cba9 1px, transparent 1px);
  background-size: 18px 18px;
}

.card {
  width: min(100%, 480px);
  padding: 32px;
  border: 3px solid #23352c;
  border-radius: 14px;
  background: #fffdf6;
  box-shadow: 8px 8px 0 #23352c;
}

.pixel-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  margin-bottom: 18px;
  border: 2px solid #23352c;
  background: #e8a45b;
  font-size: 26px;
}

.eyebrow {
  margin: 0 0 8px;
  color: #55705c;
  font-size: 0.85rem;
  font-weight: 800;
  letter-spacing: 0.12em;
}

h1 { margin: 0; font-size: clamp(2rem, 8vw, 2.7rem); line-height: 1.08; }
.intro { margin: 12px 0 26px; color: #526259; }
.fields { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.field { display: grid; gap: 8px; }
label { font-weight: 700; }

input, select {
  width: 100%;
  min-height: 50px;
  padding: 10px 12px;
  border: 2px solid #879486;
  border-radius: 7px;
  background: #fff;
  color: #23352c;
  font: inherit;
}

input:focus-visible, select:focus-visible, button:focus-visible {
  outline: 3px solid #e8a45b;
  outline-offset: 3px;
}

button {
  width: 100%;
  min-height: 52px;
  margin-top: 20px;
  padding: 12px 16px;
  border: 2px solid #23352c;
  border-radius: 7px;
  background: #55705c;
  color: #fffdf6;
  font: inherit;
  font-weight: 750;
  cursor: pointer;
  transition: background-color 120ms ease, transform 120ms ease, box-shadow 120ms ease;
}

button:hover { background: #405b48; }
button:active { transform: translateY(2px); box-shadow: inset 0 2px 3px #23352c66; }
.results { margin-top: 28px; }
h2 { margin: 0 0 12px; font-size: 1.1rem; }
#result-list { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
#result-list li { display: flex; justify-content: space-between; gap: 12px; padding: 12px 14px; border: 1px solid #d8d2c0; border-radius: 6px; background: #f8f4e9; }
.result-value { font-weight: 800; font-variant-numeric: tabular-nums; }
.ratio-note { margin: 20px 0 0; color: #667367; font-size: 0.9rem; text-align: center; }

@media (max-width: 420px) {
  .card { padding: 24px 20px; }
  .fields { grid-template-columns: 1fr; }
}

const units = [
  { id: "cups", label: "Cups", inCups: 1 },
  { id: "tablespoons", label: "Tablespoons", inCups: 1 / 16 },
  { id: "teaspoons", label: "Teaspoons", inCups: 1 / 48 },
  { id: "millilitres", label: "Millilitres", inCups: 1 / 240 }
];

const form = document.querySelector("#converter-form");
const amountInput = document.querySelector("#amount");
const unitSelect = document.querySelector("#unit");
const resultList = document.querySelector("#result-list");

function convert() {
  const amount = Number(amountInput.value);
  const source = units.find((unit) => unit.id === unitSelect.value);
  resultList.replaceChildren();

  if (!Number.isFinite(amount) || amount < 0 || !source) return;

  const amountInCups = amount * source.inCups;
  for (const unit of units) {
    if (unit.id === source.id) continue;
    const value = (amountInCups / unit.inCups).toFixed(1);
    const row = document.createElement("li");
    const label = document.createElement("span");
    const result = document.createElement("span");
    label.textContent = unit.label;
    result.className = "result-value";
    result.textContent = `${value} ${unit.id === "millilitres" ? "ml" : unit.id === "tablespoons" ? "tbsp" : unit.id === "teaspoons" ? "tsp" : "cups"}`;
    row.append(label, result);
    resultList.append(row);
  }
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  convert();
});
amountInput.addEventListener("input", convert);
unitSelect.addEventListener("change", convert);
convert();
